function withBorder(Wrapped) {
  return function WithBorder(props) {
    return <div style={{ border: '2px solid #2563eb', padding: 8 }}><Wrapped {...props} /></div>;
  };
}

function Field() {
  return <input placeholder="type here" />;
}

const BorderedField = withBorder(Field);

function App() {
  const [count, setCount] = useState(0);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setCount(count + 1)}>Count {count}</button>
      <BorderedField />
    </div>
  );
}

function withLoading(Wrapped) {
  const WithLoading = React.forwardRef(function WithLoading({ isLoading, ...rest }, ref) {
    if (isLoading) return <p style={{ fontFamily: 'system-ui' }}>Loading...</p>;
    return <Wrapped ref={ref} {...rest} />;
  });
  WithLoading.displayName = 'WithLoading(' + (Wrapped.displayName || Wrapped.name || 'Component') + ')';
  return WithLoading;
}

const Input = React.forwardRef(function Input(props, ref) {
  return <input ref={ref} {...props} />;
});

const LoadingInput = withLoading(Input);

function App() {
  const [loading, setLoading] = useState(false);
  const ref = React.useRef(null);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setLoading(l => !l)}>Toggle</button>
      <button onClick={() => ref.current && ref.current.focus()}>Focus input</button>
      <LoadingInput isLoading={loading} ref={ref} placeholder="type" />
    </div>
  );
}
